#include "networks_screens.hpp"
#include <QFile>
#include <QFileInfo>
#include <QSaveFile>
#include <QFileDialog>
#include <QMessageBox>
#include <QCheckBox>
#include <QGridLayout>
namespace tora::desktop {
NetworksController::NetworksController(QObject* parent):QObject(parent){setObjectName("networks-controller");auto* owner=qobject_cast<QWidget*>(parent);dialogs_.showError=[owner](const QString& a,const QString& b){QMessageBox::warning(owner,a,b);};dialogs_.askSave=[owner]{auto a=QMessageBox::question(owner,"Save?","Do you wish to save data?",QMessageBox::Yes|QMessageBox::No|QMessageBox::Cancel);return a==QMessageBox::Yes?SaveChoice::Yes:a==QMessageBox::No?SaveChoice::No:SaveChoice::Cancel;};dialogs_.chooseSave=[owner](const QString& current)->std::optional<QString>{auto p=QFileDialog::getSaveFileName(owner,"Save As",current,"Text Files (*.txt);;All Files (*)");return p.isEmpty()?std::nullopt:std::optional<QString>(p);};dialogs_.chooseOpen=[owner]()->std::optional<OpenSelection>{QFileDialog d(owner,"Open Network Problem");d.setFileMode(QFileDialog::ExistingFile);d.setOption(QFileDialog::DontUseNativeDialog);auto* ro=new QCheckBox("Open as read-only",&d);if(auto* l=qobject_cast<QGridLayout*>(d.layout()))l->addWidget(ro,l->rowCount(),0,1,l->columnCount());if(d.exec()!=QDialog::Accepted||d.selectedFiles().isEmpty())return {};return OpenSelection{d.selectedFiles().first(),ro->isChecked()};};}bool NetworksController::reject(QString& e,const QString& m){e=m;pendingValid_=false;return false;}
void NetworksController::modified(){dirty_=true;result_.reset();solvedGraph_={};emit changed();}
void NetworksController::beginNew(NetworkMode mode,core::NumberFormat f){(void)core::NumberFormatter(f);mode_=mode;format_=f;clipboard_.clear();selectedNode_=-1;document_.reset();undo_.reset();result_.reset();solvedGraph_={};dirty_=readOnly_=false;pendingValid_=true;path_.clear();emit inputReset();emit changed();}
bool NetworksController::initialize(NetworkMode mode,const QString& title,int count,QString& e){e.clear();if(readOnly_)return reject(e,"Save a copy before editing this read-only network.");try{auto next=NetworksDocument::blank(mode,count,title.toStdString(),format_);document_=std::move(next);mode_=mode;clipboard_.clear();selectedNode_=-1;undo_.reset();modified();emit inputReset();return true;}catch(const std::exception& x){return reject(e,x.what());}}
bool NetworksController::editCell(int r,int c,const QString& value,QString& e){e.clear();if(!document_)return reject(e,"Initialize a network first.");try{if(document_->cell(r,c)==value.toStdString())return true;if(readOnly_)return reject(e,"Save a copy before editing this read-only network.");document_->setCell(r,c,value.toStdString());undo_.reset();modified();return true;}catch(const std::exception& x){return reject(e,x.what());}}
bool NetworksController::setTitle(const QString& title,QString& e){e.clear();if(!document_||document_->title()==title.toStdString())return true;if(readOnly_)return reject(e,"Save a copy before editing this read-only network.");try{document_->setTitle(title.toStdString());undo_.reset();modified();return true;}catch(const std::exception& x){return reject(e,x.what());}}
bool NetworksController::setFormat(core::NumberFormat f,QString& e){e.clear();try{(void)core::NumberFormatter(f);if(f.n==format_.n&&f.d==format_.d&&f.notation==format_.notation)return true;if(readOnly_)return reject(e,"Save a copy before editing this read-only network.");format_=f;undo_.reset();if(document_){document_->setFormat(f);modified();}return true;}catch(const std::exception& x){return reject(e,x.what());}}
bool NetworksController::setSymmetrical(bool value,QString& e){e.clear();if(!document_||document_->symmetrical()==value)return true;if(readOnly_)return reject(e,"Save a copy before editing this read-only network.");document_->setSymmetrical(value);undo_.reset();modified();emit inputReset();return true;}
bool NetworksController::editNode(int at,bool insert,QString& e){e.clear();if(!commitInput()||!document_)return reject(e,"Initialize and correct the network before editing nodes.");if(readOnly_)return reject(e,"Save a copy before editing this read-only network.");try{auto next=*document_;if(insert)next.insertNode(at);else next.eraseNode(at);undo_=document_;document_=std::move(next);clipboard_.clear();selectedNode_=-1;modified();emit inputReset();return true;}catch(const std::exception& x){return reject(e,x.what());}}
bool NetworksController::undo(QString& e){e.clear();if(!commitInput()||!canUndo())return reject(e,"There is no editable node operation to undo.");document_=std::move(undo_);undo_.reset();clipboard_.clear();selectedNode_=-1;modified();emit inputReset();return true;}
bool NetworksController::selectLine(bool row,int position,bool before){if(!document_||position<0||position>=document_->nodes())return false;selectedRow_=row;selectedNode_=position;insertBefore_=before;return true;}
bool NetworksController::copySelection(){if(!commitInput()||!document_||selectedNode_<0)return false;clipboard_.clear();for(int i=0;i<=document_->nodes();++i)clipboard_.push_back(document_->cell(selectedRow_?selectedNode_+1:i,selectedRow_?i:selectedNode_+1));return true;}
bool NetworksController::pasteSelection(QString& e){e.clear();if(!commitInput()||!document_||selectedNode_<0)return reject(e,"Select a node row or column heading first.");if(readOnly_)return reject(e,"Save a copy before editing this read-only network.");if(clipboard_.size()!=static_cast<std::size_t>(document_->nodes()+1))return reject(e,"Copy a row or column from the current network first.");try{auto next=*document_;for(int i=0;i<=next.nodes();++i)if(i!=selectedNode_+1)next.setCell(selectedRow_?selectedNode_+1:i,selectedRow_?i:selectedNode_+1,clipboard_[static_cast<std::size_t>(i)]);document_=std::move(next);undo_.reset();modified();emit inputReset();return true;}catch(const std::exception& x){return reject(e,x.what());}}
bool NetworksController::editSelection(bool insert,QString& e){if(selectedNode_<0)return reject(e,"Select a node row or column heading first.");return editNode(selectedNode_+(insert&&!insertBefore_?1:0),insert,e);}
bool NetworksController::openFile(const QString& p,QString& e,bool ro){e.clear();QFile f(p);if(!f.open(QIODevice::ReadOnly))return reject(e,f.errorString());if(f.size()>4*1024*1024)return reject(e,"Network file exceeds the 4 MiB limit.");try{auto bytes=f.readAll();if(f.error()!=QFileDevice::NoError)return reject(e,f.errorString());auto next=NetworksDocument::decode(std::string_view(bytes.constData(),static_cast<std::size_t>(bytes.size())),mode_);document_=std::move(next);clipboard_.clear();selectedNode_=-1;format_=document_->format();path_=p;readOnly_=ro;dirty_=false;undo_.reset();result_.reset();solvedGraph_={};emit inputReset();emit changed();return true;}catch(const std::exception& x){return reject(e,x.what());}}
bool NetworksController::commitInput(){pendingValid_=true;emit commitRequested();return pendingValid_;}
bool NetworksController::saveTo(const QString& p,QString& e){e.clear();if(!commitInput())return reject(e,"Correct the active input before saving.");if(!document_||p.isEmpty())return reject(e,"Initialize a network and choose a filename.");auto identity=[](const QString& s){QFileInfo f(s);return f.exists()?f.canonicalFilePath():f.absoluteFilePath();};if(readOnly_&&identity(p)==identity(path_))return reject(e,"The source is read-only. Save to a different file.");const auto bytes=document_->encode();QSaveFile f(p);if(!f.open(QIODevice::WriteOnly)||f.write(bytes.data(),static_cast<qint64>(bytes.size()))!=static_cast<qint64>(bytes.size())||!f.commit())return reject(e,f.errorString());path_=p;dirty_=readOnly_=false;emit inputReset();emit changed();return true;}
bool NetworksController::solve(int source,int sink,QString& e,NetworkRouteMethod method){e.clear();if(!commitInput()||!document_)return reject(e,"Initialize and correct the network before solving.");try{auto graph=document_->graph();NetworkResult next;if(mode_==NetworkMode::MinimalTree)next=networks::minimumSpanningForestPrim(graph,source<0?graph.nodeCount:static_cast<std::size_t>(source));else if(mode_==NetworkMode::ShortestRoute){if(method==NetworkRouteMethod::Floyd||method==NetworkRouteMethod::ShortestRoutes)next=networks::floydWarshall(graph,method==NetworkRouteMethod::Floyd);else if(method==NetworkRouteMethod::Dijkstra)next=networks::dijkstra(graph,source<0?graph.nodeCount:static_cast<std::size_t>(source));else next=networks::shortestRoutes(graph,source<0?graph.nodeCount:static_cast<std::size_t>(source));}else{networks::FlowOptions options;options.recordTrace=true;next=networks::maximumFlow(graph,source<0?graph.nodeCount:static_cast<std::size_t>(source),sink<0?graph.nodeCount:static_cast<std::size_t>(sink),options);}result_=std::move(next);solvedGraph_=std::move(graph);source_=source;sink_=sink;routeMethod_=method;emit changed();return true;}catch(const std::exception& x){return reject(e,x.what());}}
bool NetworksController::requestSave(){if(!commitInput()||!document_)return false;auto p=dialogs_.chooseSave(path_);if(!p)return false;QString e;if(saveTo(*p,e))return true;dialogs_.showError("Cannot Save Problem",e);return false;}
bool NetworksController::leaveInput(){if(!commitInput())return false;if(!dirty_)return true;auto a=dialogs_.askSave();return a==SaveChoice::No||(a==SaveChoice::Yes&&requestSave());}
bool NetworksController::requestOpen(){auto p=dialogs_.chooseOpen();if(!p||!leaveInput())return false;QString e;if(openFile(p->path,e,p->readOnly))return true;dialogs_.showError("Cannot Open Problem",e);return false;}
QStringList NetworksController::iterationText()const{
 QStringList lines;if(!document_||!result_)return lines;core::NumberFormatter format(document_->format());auto number=[&](double v){return QString::fromStdString(format.format(v));};auto name=[&](std::size_t i){return QString::fromStdString(document_->nodeName(static_cast<int>(i)));};
 if(const auto* r=std::get_if<networks::SpanningForest>(&*result_)){long double value=0;for(auto i:r->edgeIndices){const auto& e=solvedGraph_.edges[i];value+=e.value;lines.append("Connect "+name(e.from)+" -- "+name(e.to)+"; updated tree length = "+number(static_cast<double>(value)));}}
 else if(const auto* r=std::get_if<networks::ShortestRoutes>(&*result_)){for(const auto& step:r->dijkstraTrace){QString line="Settle "+name(step.permanentNode)+"\nNode: distance, predecessor, status\n";for(std::size_t i=0;i<step.distance.size();++i)line+=name(i)+": "+(step.distance[i]?number(*step.distance[i]):"infinity")+", "+(step.predecessor[i]?name(*step.predecessor[i]):"--")+", "+(step.permanent[i]?"permanent":"temporary")+"\n";lines.append(line);}for(const auto& step:r->trace)lines.append(QString("Pass %1: ").arg(step.pass)+name(step.from)+" -> "+name(step.to)+"; distance to "+name(step.to)+" = "+number(step.distance));if(r->traceTruncated)lines.append("Trace storage limit reached; route calculation completed.");}
 else if(const auto* r=std::get_if<networks::AllPairsRoutes>(&*result_)){for(const auto& step:r->trace){QString line=step.initial?"Initial distance and next-node matrices\n":"Allow intermediate "+name(step.intermediate)+"\n";const auto count=solvedGraph_.nodeCount;for(std::size_t i=0;i<count;++i){line+=name(i)+": ";for(std::size_t j=0;j<count;++j){const auto at=i*count+j;line+=(step.distance[at]?number(*step.distance[at]):"infinity")+" ["+(step.next[at]?name(*step.next[at]):"--")+"]  ";}line+='\n';}lines.append(line);}if(r->traceTruncated)lines.append("A matrix exceeded the display scalar range; route calculation completed.");}
 else if(const auto* r=std::get_if<networks::MaximumFlow>(&*result_)){for(const auto& step:r->trace){QString path;for(std::size_t i=0;i<step.nodes.size();++i){if(i)path+=step.backward[i-1]?" <-cancel- ":" -> ";path+=name(step.nodes[i]);}lines.append(path+"; augment = "+number(step.amount));}if(r->traceTruncated)lines.append("Trace storage limit reached; flow calculation completed.");}
 return lines;
}
QString NetworksController::outputText()const{if(!document_||!result_)return {};core::NumberFormatter f(document_->format());auto number=[&](double v){return QString::fromStdString(f.format(v));};auto name=[&](std::size_t i){return QString::fromStdString(document_->nodeName(static_cast<int>(i)));};QString out=QString::fromStdString(document_->title())+'\n';if(const auto* r=std::get_if<networks::SpanningForest>(&*result_)){out+=(r->connected?"Minimal Spanning Tree\n":"Disconnected network: minimum spanning forest\n");out+="Total length = "+number(r->totalWeight)+'\n';out+=QString("Components = %1\n").arg(r->componentCount);for(auto i:r->edgeIndices){const auto& e=solvedGraph_.edges[i];out+=name(e.from)+" -- "+name(e.to)+" = "+number(e.value)+'\n';}}else if(const auto* r=std::get_if<networks::ShortestRoutes>(&*result_)){out+="Shortest Route from "+name(r->source)+'\n';for(std::size_t i=0;i<r->routes.size();++i){const auto& route=r->routes[i];out+=name(i)+": ";if(route.status==networks::RouteStatus::Unreachable)out+="Unreachable\n";else if(route.status==networks::RouteStatus::NegativeCycle)out+="Unbounded below (reachable negative cycle)\n";else{out+=number(*route.distance)+" : ";for(std::size_t j=0;j<route.nodes.size();++j){if(j)out+=" -> ";out+=name(route.nodes[j]);}out+='\n';}}if(!r->negativeCycleNodes.empty()){out+="Negative cycle: ";for(auto n:r->negativeCycleNodes)out+=name(n)+' ';out+='\n';}}else if(const auto* r=std::get_if<networks::AllPairsRoutes>(&*result_)){out+="All-pairs Shortest Routes\n";for(const auto& from:r->sources){out+="From "+name(from.source)+'\n';for(std::size_t i=0;i<from.routes.size();++i){const auto& route=from.routes[i];out+=name(i)+": ";if(route.status==networks::RouteStatus::Unreachable)out+="Unreachable\n";else if(route.status==networks::RouteStatus::NegativeCycle)out+="Unbounded below (reachable negative cycle)\n";else {out+=number(*route.distance)+" : ";for(std::size_t j=0;j<route.nodes.size();++j){if(j)out+=" -> ";out+=name(route.nodes[j]);}out+='\n';}}}}else if(const auto* r=std::get_if<networks::MaximumFlow>(&*result_)){out+="Maximal Flow: "+name(static_cast<std::size_t>(source_))+" -> "+name(static_cast<std::size_t>(sink_))+'\n';out+="Value = "+number(r->value)+"; minimum cut = "+number(r->cutCapacity)+'\n';for(std::size_t i=0;i<solvedGraph_.edges.size();++i){const auto& e=solvedGraph_.edges[i];out+=name(e.from)+" -> "+name(e.to)+" = "+number(r->edgeFlow[i])+" / "+number(e.value)+'\n';}out+="Source side of cut: ";for(std::size_t i=0;i<r->sourceSide.size();++i)if(r->sourceSide[i])out+=name(i)+' ';out+=QString("\nAugmentations = %1\n").arg(r->augmentationCount);}return out;}
NetworksController& networksController(ApplicationShell& shell){if(auto* c=shell.findChild<NetworksController*>("networks-controller"))return *c;return *new NetworksController(&shell);}
}
